      <input id="pg-nome" class="inp" type="text" value="{{nome}}" onChange="{{onNome}}" placeholder="Como voc\xEA quer ser chamado" autocomplete="given-name" style="height: 58px; box-sizing: border-box; border: 2px solid #c7d7f2; border-radius: 18px; background: #ffffff; padding: 0 18px; font-family: Nunito, sans-serif; font-size: 18px; font-weight: 800; color: #1e3a8a">
    </div>
